"use client";

import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { Cause } from "@/types/causes";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";

interface CompletedCauseDetailsSheetProps {
  cause: Cause | null;
  isOpen: boolean;
  onClose: () => void;
}

export function CompletedCauseDetailsSheet({
  cause,
  isOpen,
  onClose,
}: CompletedCauseDetailsSheetProps) {
  if (!cause) return null;

  return (
    <Sheet open={isOpen} onOpenChange={onClose}>
      <SheetContent className="w-[400px] sm:w-[540px]">
        <SheetHeader>
          <SheetTitle>Cause Details</SheetTitle>
        </SheetHeader>
        <div className="mt-6 space-y-6">
          <div className="flex items-center gap-4">
            <Avatar className="h-16 w-16">
              <AvatarImage src={cause.image} alt={cause.name} />
              <AvatarFallback>{cause.name.slice(0, 2)}</AvatarFallback>
            </Avatar>
            <div>
              <h3 className="text-lg font-semibold">{cause.name}</h3>
              <p className="text-sm text-muted-foreground">{cause.organization}</p>
            </div>
          </div>

          <Card>
            <CardContent className="pt-6">
              <div className="grid gap-4">
                <div className="flex justify-between">
                  <span className="text-sm text-muted-foreground">Category</span>
                  <Badge variant="secondary" className="capitalize">
                    {cause.category}
                  </Badge>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-muted-foreground">Final Amount</span>
                  <span className="font-medium">{cause.currentlyWinning.amount}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-muted-foreground">Completed On</span>
                  <span>{cause.endsOn}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-muted-foreground">Total Benefactors</span>
                  <span>{cause.benefactors}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-muted-foreground">Final Points</span>
                  <div className="text-right">
                    <div className="font-medium">{cause.points.count}</div>
                    <div className="text-sm text-muted-foreground">{cause.points.label}</div>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>

          <div className="space-y-4">
            <h4 className="font-medium">Impact Summary</h4>
            <Card>
              <CardContent className="pt-6">
                <div className="space-y-4">
                  <div className="flex justify-between">
                    <span className="text-sm text-muted-foreground">Total Donations</span>
                    <span className="font-medium">{cause.currentlyWinning.amount}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-sm text-muted-foreground">Duration</span>
                    <span>From {cause.startedOn} to {cause.endsOn}</span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-sm text-muted-foreground">Type</span>
                    <span className="capitalize">{cause.type}</span>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
} 