"use client";

import { ColumnDef } from "@tanstack/react-table";
import { Badge } from "@/components/ui/badge";
import { Cause } from "@/types/causes";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { MoreHorizontal } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

export const completedCauseColumns: ColumnDef<Cause>[] = [
  {
    accessorKey: "name",
    header: "Cause",
    cell: ({ row }) => {
      const cause = row.original;
      return (
        <div className="flex items-center gap-4">
          <Avatar className="h-10 w-10">
            <AvatarImage src={cause.image} alt={cause.name} />
            <AvatarFallback>{cause.name.slice(0, 2)}</AvatarFallback>
          </Avatar>
          <div className="flex flex-col">
            <span className="font-medium">{cause.name}</span>
            <span className="text-sm text-muted-foreground">
              {cause.organization}
            </span>
          </div>
        </div>
      );
    },
  },
  {
    accessorKey: "category",
    header: "Category",
    cell: ({ row }) => {
      return (
        <Badge variant="secondary" className="capitalize">
          {row.original.category}
        </Badge>
      );
    },
  },
  {
    accessorKey: "finalAmount",
    header: "Final Amount",
    cell: ({ row }) => {
      return <span>{row.original.currentlyWinning.amount}</span>;
    },
  },
  {
    accessorKey: "completedOn",
    header: "Completed On",
    cell: ({ row }) => {
      return <span>{row.original.endsOn}</span>;
    },
  },
  {
    accessorKey: "totalBenefactors",
    header: "Total Benefactors",
    cell: ({ row }) => {
      return <span>{row.original.benefactors}</span>;
    },
  },
  {
    accessorKey: "finalPoints",
    header: "Final Points",
    cell: ({ row }) => {
      return (
        <div className="flex flex-col">
          <span>{row.original.points.count}</span>
          <span className="text-sm text-muted-foreground">
            {row.original.points.label}
          </span>
        </div>
      );
    },
  },
  {
    id: "actions",
    cell: ({ row }) => {
      return (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" className="h-8 w-8 p-0">
              <span className="sr-only">Open menu</span>
              <MoreHorizontal className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuLabel>Actions</DropdownMenuLabel>
            <DropdownMenuSeparator />
            <DropdownMenuItem>View Details</DropdownMenuItem>
            <DropdownMenuItem>View Analytics</DropdownMenuItem>
            <DropdownMenuItem>Download Report</DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      );
    },
  },
]; 